configuration.tbelDecoder:
// 1. Parsing sicuro e garantito di payload e metadata
var data = {};
try {
    data = decodeToJson(payload);
    if (!data) {
        data = JSON.parse(payloadBytesToString(payload));
    }
} catch (e) {
    data = {};
}

// 2. Isolamento sicuro dei metadati
var meta = (typeof metadata !== 'undefined' && metadata) ? metadata : {};
var topic = meta.topic || (data && data.topic ? data.topic : "");

// 3. Estrazione dati payload
var p = (data && data.payload) ? data.payload : (data || {});

// 4. Determinazione del nome dispositivo
var deviceName = "sensore_001";
if (topic && topic.indexOf('/') !== -1) {
    var parts = topic.split('/');
    if (parts.length >= 2 && parts[1]) {
        deviceName = parts[1];
    }
} else if (p.device_id) {
    deviceName = String(p.device_id);
}

// 5. Estrazione sicura sotto-oggetti
var hw = p.hw || {};
var analysis = p.analysis || {};
var ram = hw.ram || {};
var disk = hw.disk || {};

// 6. Costruzione oggetto telemetria
var cleanTelemetry = {
    spore_count: Number(analysis.spore_count || 0),
    detected: analysis.detected ? 1 : 0,
    frame_id: Number(p.frame_id || 0),
    sample_id: String(p.sample_id || ""),
    cpu_temp_c: Number(hw.cpu_temp_c || 0),
    processing_time_s: Number(hw.processing_time_s || 0),
    ram_used_percent: Number(ram.used_percent || 0),
    disk_used_percent: Number(disk.used_percent || 0)
};

if (p.prova !== undefined) {
    cleanTelemetry.prova = p.prova;
}

return {
   deviceName: deviceName,
   deviceType: "Optical Biosensor",
   telemetry: cleanTelemetry
};
